#include <stdint.h>
#include "led.h"
#include "uart.h"
#include "timebase.h"
#include "osKernel.h"

// #if !defined(__SOFT_FP__) && defined(__ARM_FP)
//   #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
// #endif

#define QUANTA 	10U
typedef uint32_t TaskProfiler;

TaskProfiler task_0_profiler, task_1_profiler, task_2_profiler, task_3_profiler;
volatile TaskProfiler task_4_profiler;

typedef uint32_t SemaphoreType;
SemaphoreType uart_semaphore;

void task3(void) {
	task_3_profiler++;
}

void task0(void) {
	while(1) {
		osSemaphoreWait(&uart_semaphore);
		task_0_profiler++;
		osSemaphoreGive(&uart_semaphore);
	}
}

void task1(void) {
	while(1) {
		osSemaphoreWait(&uart_semaphore);
		task_1_profiler++;
		osSemaphoreGive(&uart_semaphore);
	}
}

void task2(void) {
	while(1) {
		task_2_profiler++;
	}
}

/* this function is called only 1 time when the system starts */
int main(void) {
	/*Init TIM2*/
	tim2_1hz_interrupt_init();

	/* Create Semaphore */
	osSemaphoreCreate(&uart_semaphore, 1);

	/* Init OS */
	osKernelAddThreads(&task0, &task1, &task2);

	/* Start OS */
	osKernelLaunch(QUANTA);
}

void TIM2_IRQHandler(void) {
	/* clear interrupt flag*/
	TIM2->SR &= ~SR_UIF;
	/* task() */
	task_4_profiler++;
}



